async (page) => {
  const { exec } = require('child_process');
  const fs = require('fs');

  // Make the script executable
  exec('chmod +x /tmp/workspace/network_monitor.sh', (error, stdout, stderr) => {
    if (error) {
      console.error(`Error making script executable: ${error}`);
      return;
    }
    console.log('Script made executable successfully');
  });

  // Start the monitoring script in the background
  exec('nohup /tmp/workspace/network_monitor.sh > /dev/null 2>&1 &', (error, stdout, stderr) => {
    if (error) {
      console.error(`Error starting script: ${error}`);
      return;
    }
    console.log('Network monitoring script started in background');
  });

  return 'Commands executed to make script executable and start it in background';
}

